import React, { useState } from 'react';
import SectionHeader from './SectionHeader';
import { PROJECTS } from '../constants';
import { ExternalLink, Layers, Building2, Tag } from 'lucide-react';

const CATEGORIES = ['All', 'HRMIS', 'MIS', 'GIS', 'ERP'];

const ProjectsSection: React.FC = () => {
  const [activeTab, setActiveTab] = useState('All');

  const filteredProjects = activeTab === 'All' 
    ? PROJECTS 
    : PROJECTS.filter(p => p.category === activeTab);

  return (
    <section id="projects" className="py-24 px-6 bg-[#080808]">
      <div className="max-w-7xl mx-auto">
        <SectionHeader title="Enterprise Portfolios" subtitle="Impact Solutions" />

        {/* Filters */}
        <div className="flex flex-wrap gap-4 mb-12">
          {CATEGORIES.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveTab(cat)}
              className={`px-6 py-2 rounded-full text-sm font-medium transition-all duration-300 ${
                activeTab === cat 
                ? 'bg-cyan-500 text-black shadow-lg shadow-cyan-500/20' 
                : 'bg-zinc-900 text-zinc-400 border border-zinc-800 hover:border-zinc-700'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {filteredProjects.map(project => (
            <div key={project.id} className="group relative glass rounded-3xl overflow-hidden border-white/5 hover:border-cyan-500/30 transition-all duration-500">
              <div className="aspect-video overflow-hidden">
                <img 
                  src={project.imageUrl} 
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105 opacity-60 group-hover:opacity-100"
                />
              </div>

              <div className="p-8">
                <div className="flex justify-between items-start mb-4">
                  <span className="px-3 py-1 bg-cyan-500/10 text-cyan-500 text-[10px] uppercase font-bold tracking-widest rounded-md border border-cyan-500/20">
                    {project.category}
                  </span>
                  <div className="flex gap-4 text-zinc-500">
                    <button className="hover:text-cyan-500 transition-colors">
                      <ExternalLink size={18} />
                    </button>
                  </div>
                </div>

                <h3 className="text-2xl font-bold text-white mb-3 group-hover:text-cyan-400 transition-colors">
                  {project.title}
                </h3>

                <p className="text-zinc-400 text-sm leading-relaxed mb-6">
                  {project.description}
                </p>

                <div className="flex flex-col gap-4 border-t border-zinc-800 pt-6">
                  <div className="flex items-center gap-3 text-xs text-zinc-500">
                    <Building2 size={14} className="text-cyan-500" />
                    <span>Client: <span className="text-zinc-300 font-medium">{project.organization}</span></span>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {project.techStack.map(tech => (
                      <span key={tech} className="text-[10px] font-mono text-zinc-600">
                        #{tech}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

