    { name: 'Projects', href: '#projects' },
    { name: 'Contact', href: '#contact' },
  ];

  const toggleMenu = () => setIsMenuOpen(!isMenuOpen);

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsMenuOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
      // Small delay on mobile to let the menu close transition start before scrolling
      const delay = isMenuOpen ? 300 : 0;
      setTimeout(() => {
        element.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      }, delay);
    }
  };

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${scrolled || isMenuOpen ? 'glass py-4 shadow-xl border-b border-white/5' : 'py-8 bg-transparent border-b border-transparent'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <a href="#" className="text-xl font-bold text-white tracking-tighter flex items-center gap-2 relative z-50" onClick={(e) => { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); setIsMenuOpen(false); }}>
          <div className="w-8 h-8 rounded-lg bg-cyan-500 flex items-center justify-center text-black font-black shadow-lg shadow-cyan-500/20">K</div>
          KHALID<span className="text-cyan-500">.</span>
        </a>

        {/* Desktop Menu */}
        <div className="hidden md:flex items-center gap-10">
          {links.map(link => (
            <a 
              key={link.name} 
              href={link.href} 
              onClick={(e) => handleLinkClick(e, link.href)}
              className="text-sm font-medium text-zinc-400 hover:text-white transition-colors uppercase tracking-widest"
            >
              {link.name}
            </a>
          ))}
          <a 
            href="#contact" 
            onClick={(e) => handleLinkClick(e, '#contact')}
            className="px-6 py-2 bg-white text-black text-sm font-bold rounded-full hover:bg-cyan-500 transition-all transform hover:scale-105 active:scale-95 shadow-lg shadow-white/5"
          >
            HIRE ME
          </a>
        </div>

        {/* Mobile Toggle Button */}
        <button 
          className="md:hidden text-white relative z-50 p-2 hover:bg-zinc-800 rounded-xl transition-colors"
          onClick={toggleMenu}
          aria-label="Toggle Menu"
        >
          {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      <div className={`md:hidden fixed inset-0 w-full h-screen bg-[#050505] transition-all duration-500 ease-in-out origin-top ${isMenuOpen ? 'translate-y-0 opacity-100 visible' : '-translate-y-full opacity-0 invisible'}`}>
        <div className="flex flex-col items-center justify-center h-full gap-8 px-6">
          {links.map((link, idx) => (
            <a 
              key={link.name} 
              href={link.href} 
              onClick={(e) => handleLinkClick(e, link.href)}
              className={`text-2xl font-bold text-zinc-400 hover:text-white transition-all uppercase tracking-[0.2em] transform ${isMenuOpen ? 'translate-y-0' : 'translate-y-10'}`}
              style={{ transitionDelay: `${idx * 100}ms` }}
            >
              {link.name}
            </a>
          ))}
          <a 
            href="#contact" 
            onClick={(e) => handleLinkClick(e, '#contact')}
            className={`mt-8 px-12 py-4 bg-cyan-500 text-black text-lg font-black rounded-2xl transition-all transform ${isMenuOpen ? 'translate-y-0' : 'translate-y-10'}`}
            style={{ transitionDelay: `${links.length * 100}ms` }}
          >
            HIRE ME
          </a>

          <div className={`mt-auto mb-12 flex gap-8 text-zinc-500 transform transition-all ${isMenuOpen ? 'translate-y-0' : 'translate-y-10'}`} style={{ transitionDelay: `${(links.length + 1) * 100}ms` }}>
