import React, { useState, useEffect } from 'react';
import { Menu, X, User, Cpu, Layers, Briefcase, Mail } from 'lucide-react';

const Navigation: React.FC = () => {
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const links = [
    { name: 'About', href: '#about', icon: <User size={16} /> },
    { name: 'Skills', href: '#skills', icon: <Cpu size={16} /> },
    { name: 'Projects', href: '#projects', icon: <Layers size={16} /> },
    { name: 'Experience', href: '#experience', icon: <Briefcase size={16} /> },
    { name: 'Contact', href: '#contact', icon: <Mail size={16} /> },
  ];

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsMenuOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
      const delay = isMenuOpen ? 300 : 0;
      setTimeout(() => {
        element.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      }, delay);
    }
  };

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-500 ${scrolled ? 'bg-[#050505]/80 backdrop-blur-xl border-b border-white/5 py-4' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        {/* Logo */}
        <a href="#" className="flex items-center gap-2 group" onClick={(e) => { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); }}>
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center text-white shadow-lg shadow-cyan-500/20 group-hover:scale-110 transition-transform">
            <span className="text-xl font-black">{'>_'}</span>
          </div>
          <span className="text-xl font-bold text-white tracking-tight">Khalid<span className="text-cyan-500">.</span>Sys</span>
        </a>

        {/* Desktop Links */}
        <div className="hidden md:flex items-center gap-8">
          {links.map(link => (
            <a 
              key={link.name} 
              href={link.href} 
              onClick={(e) => handleLinkClick(e, link.href)}
              className="group flex items-center gap-2 text-sm font-medium text-zinc-400 hover:text-white transition-all"
            >
              <span className="text-zinc-600 group-hover:text-cyan-500 transition-colors">
                {link.icon}
              </span>
              {link.name}
            </a>
          ))}
        </div>

        {/* Mobile Button */}
        <button 
          className="md:hidden text-white p-2 relative z-50"
          onClick={() => setIsMenuOpen(!isMenuOpen)}
        >
          {isMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden fixed inset-0 z-40 bg-[#050505]/fb backdrop-blur-3xl flex flex-col items-center justify-center gap-10 transition-all duration-500 ${isMenuOpen ? 'opacity-100 visible' : 'opacity-0 invisible pointer-events-none'}`}>
        {links.map((link, idx) => (
          <a 
            key={link.name} 
            href={link.href} 
            onClick={(e) => handleLinkClick(e, link.href)}
            className={`flex items-center gap-4 text-3xl font-bold text-zinc-500 hover:text-white uppercase tracking-[0.2em] transition-all transform ${isMenuOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}
            style={{ transitionDelay: `${idx * 100}ms` }}
          >
            <span className="text-cyan-500">{link.icon}</span>
            {link.name}
          </a>
        ))}

        {/* Decorative elements for mobile menu */}
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex gap-6 opacity-30">
           <div className="w-1.5 h-1.5 rounded-full bg-cyan-500"></div>
           <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>
           <div className="w-1.5 h-1.5 rounded-full bg-cyan-500"></div>
        </div>
      </div>
    </nav>
  );
};

