  if (selectedProject) {
    return <ProjectDetailView project={selectedProject} onBack={handleBackToHome} />;
  }

  return (
    <div className="min-h-screen">
      <Navigation />

      <main>
        <Hero />
        <About />
        <SkillsSection />
        <ExperienceTimeline />
        <ProjectsSection onSelectProject={handleSelectProject} />
        <CertificationsGrid />
        <Contact />
      </main>

      <Footer />
